	public static void main(String[] args){
		Scanner scanner = new Scanner(System.in);
    int w = scanner.nextInt();
    int b = scanner.nextInt();
    String pattern = "wbwbwwbwbwbw";
    StringBuilder sb = new StringBuilder();
    while (sb.length() < 200) {
        sb.append(pattern);
    }
    String extendedPattern = sb.toString();

    boolean found = false;
    for (int i = 0; i <= extendedPattern.length() - (w + b); i++) {
        String substring = extendedPattern.substring(i, i + w + b);
        long countW = substring.chars().filter(ch -> ch == 'w').count();
        long countB = substring.chars().filter(ch -> ch == 'b').count();
        if (countW == w && countB == b) {
            found = true;
            break;
        }
    }

    if (found) {
        System.out.println("Yes");
    } else {
        System.out.println("No");
    }
	}

